function TimeoutForgePure(){

  function num(v){ var n = Number(v); return isFinite(n) ? n : null; }

  // 每行：名称 超时ms [P99ms] [尝试次数] [退避ms]
  function parseChain(text){
    var lines = String(text == null ? '' : text).split(/\r?\n/), rows = [], errors = [];
    for (var i = 0; i < lines.length; i++){
      var raw = lines[i].replace(/#.*$/, '').trim();
      if (raw === '') continue;
      var f = raw.split(/[\s,]+/);
      if (f.length < 2){ errors.push('第 ' + (i + 1) + ' 行至少要有「名称 超时」两列：' + raw); continue; }
      var t = num(f[1]);
      if (t === null || t <= 0){ errors.push('第 ' + (i + 1) + ' 行超时非法：' + f[1]); continue; }
      var p99 = f.length > 2 ? num(f[2]) : null;
      var att = f.length > 3 ? num(f[3]) : 1;
      var back = f.length > 4 ? num(f[4]) : 0;
      if (att === null || att < 1 || att % 1 !== 0){ errors.push('第 ' + (i + 1) + ' 行尝试次数须为正整数：' + f[3]); continue; }
      if (back === null || back < 0){ errors.push('第 ' + (i + 1) + ' 行退避非法：' + f[4]); continue; }
      rows.push({depth:rows.length, name:f[0], timeout:t, p99:p99, attempts:att, backoff:back, line:i + 1});
    }
    if (!rows.length) errors.push('没有解析到任何一层，格式为「名称 超时ms [P99ms] [尝试次数] [退避ms]」');
    return {value:rows, errors:errors, ok:errors.length === 0};
  }

  // 一层在最坏情况下真正会占用多久：所有尝试都跑满超时，中间还要退避
  function worstCase(layer){
    var t = Number(layer.timeout), a = Number(layer.attempts) || 1, b = Number(layer.backoff) || 0;
    return a * t + (a - 1) * b;
  }

  function amplification(rows){
    var prod = 1, out = [];
    for (var i = 0; i < rows.length; i++){
      prod *= rows[i].attempts;
      out.push({name:rows[i].name, attempts:rows[i].attempts, cumulative:prod});
    }
    return {value:out, factor:prod};
  }

  // 超时倒挂：下游最坏耗时不该超过上游给的窗口
  function audit(rows){
    var issues = [], i;
    function err(name, msg){ issues.push({level:'error', layer:name, msg:msg}); }
    function warn(name, msg){ issues.push({level:'warn', layer:name, msg:msg}); }
    function ok(name, msg){ issues.push({level:'ok', layer:name, msg:msg}); }

    for (i = 0; i < rows.length; i++){
      var L = rows[i], w = worstCase(L);
      L.worst = w;
      if (L.p99 !== null){
        if (L.timeout < L.p99)
          err(L.name, '超时 ' + L.timeout + 'ms 低于自身 P99 ' + L.p99 + 'ms，会稳定砍掉本来能成功的长尾请求');
        else if (L.timeout < L.p99 * 1.3)
          warn(L.name, '超时 ' + L.timeout + 'ms 仅为 P99 的 ' + (L.timeout / L.p99).toFixed(2) + ' 倍，抖动一下就集体超时');
        else if (L.timeout > L.p99 * 10)
          warn(L.name, '超时 ' + L.timeout + 'ms 是 P99 的 ' + (L.timeout / L.p99).toFixed(0) + ' 倍，故障时连接和线程会被长时间占死');
        else
          ok(L.name, '超时相对 P99 留了 ' + (L.timeout / L.p99).toFixed(1) + ' 倍余量，合理');
      }
      if (i > 0){
        var up = rows[i - 1];
        if (L.timeout >= up.timeout)
          err(L.name, '超时 ' + L.timeout + 'ms 不小于上游 ' + up.name + ' 的 ' + up.timeout + 'ms，上游会先放弃，本层的等待纯属浪费');
        if (w > up.timeout)
          err(L.name, '含重试的最坏耗时 ' + w + 'ms 超过上游窗口 ' + up.timeout + 'ms，重试永远跑不完就被上游掐断');
        else if (w > up.timeout * 0.9)
          warn(L.name, '最坏耗时 ' + w + 'ms 已吃掉上游窗口的 ' + (w / up.timeout * 100).toFixed(0) + '%，几乎没给上游留处理时间');
      }
    }
    var errors = 0, warns = 0;
    for (i = 0; i < issues.length; i++){
      if (issues[i].level === 'error') errors++;
      else if (issues[i].level === 'warn') warns++;
    }
    return {issues:issues, errors:errors, warnings:warns, ok:errors === 0,
            grade:errors ? '存在倒挂' : (warns ? '偏紧或偏松' : '预算自洽')};
  }

  // 自顶向下按比例切预算：每层留一份自留时间给自己的处理与网络
  function allocate(totalMs, layers, reservePct){
    var t = Number(totalMs), n = Number(layers);
    var pct = reservePct === undefined ? 0.15 : Number(reservePct);
    if (!isFinite(t) || t <= 0) return {error:'总预算必须为正'};
    if (!isFinite(n) || n < 1 || n % 1 !== 0) return {error:'层数必须是正整数'};
    if (!isFinite(pct) || pct <= 0 || pct >= 1) return {error:'自留比例需在 0 到 1 之间'};
    var rows = [], remain = t;
    for (var i = 0; i < n; i++){
      var reserve = remain * pct, give = remain - reserve;
      rows.push({depth:i + 1, budget:remain, reserve:reserve, downstream:give,
                 suggestTimeout:Math.floor(give)});
      remain = give;
    }
    return {value:rows, tail:remain, shrink:1 - remain / t};
  }

  // 由观测分位数反推一个合适的超时
  function recommend(p50, p99, p999){
    var a = num(p50), b = num(p99), c = num(p999);
    if (a === null || b === null) return {error:'至少要给出 P50 与 P99'};
    if (a <= 0 || b <= 0) return {error:'分位数必须为正'};
    if (b < a) return {error:'P99 不应小于 P50'};
    if (c !== null && c < b) return {error:'P999 不应小于 P99'};
    var tail = b / a;
    var factor = tail > 10 ? 1.5 : tail > 4 ? 2 : 3;   // 长尾越重，越不该按倍数外推
    var base = c !== null ? Math.max(b * factor, c * 1.2) : b * factor;
    return {value:Math.ceil(base), factor:factor, tailRatio:tail,
            basis:c !== null ? 'max(P99 × ' + factor + ', P999 × 1.2)' : 'P99 × ' + factor,
            note:tail > 10 ? '尾部离散度很高，比起放大超时更该先治理长尾' : '尾部形态正常，按分位数外推即可'};
  }

  // Google SRE 的重试预算：重试量占正常量的比例设上限
  function retryBudget(rps, attempts, ratio){
    var r = num(rps), a = num(attempts), q = ratio === undefined ? 0.1 : num(ratio);
    if (r === null || r <= 0) return {error:'RPS 必须为正'};
    if (a === null || a < 1 || a % 1 !== 0) return {error:'尝试次数必须是正整数'};
    if (q === null || q <= 0 || q >= 1) return {error:'预算比例需在 0 到 1 之间'};
    var worstExtra = r * (a - 1);
    var allowed = r * q;
    var maxFailRate = a > 1 ? q / (a - 1) : 1;
    return {value:{
      normalRps:r, worstExtraRps:worstExtra, allowedExtraRps:allowed,
      exceeded:worstExtra > allowed,
      maxFailRate:maxFailRate,
      verdict:worstExtra > allowed
        ? '全量失败时重试会额外打出 ' + worstExtra.toFixed(0) + ' RPS，是 ' + (q * 100).toFixed(0) +
          '% 预算（' + allowed.toFixed(0) + ' RPS）的 ' + (worstExtra / allowed).toFixed(1) + ' 倍，必须上重试预算或熔断'
        : '最坏额外 ' + worstExtra.toFixed(0) + ' RPS 仍在预算内',
      guidance:'失败率超过 ' + (maxFailRate * 100).toFixed(1) + '% 时就应停止重试，把容量留给还能成功的请求'
    }};
  }

  // 对冲请求：等到某分位数还没回来就再发一份
  function hedge(p50, p99, atPercentile){
    var a = num(p50), b = num(p99), q = num(atPercentile);
    if (a === null || b === null) return {error:'需要 P50 与 P99'};
    if (q === null || q <= 0 || q >= 1) return {error:'对冲触发分位数需在 0 到 1 之间'};
    if (b < a) return {error:'P99 不应小于 P50'};
    // 用对数插值近似触发点的延迟
    var lo = Math.log(a), hi = Math.log(b);
    var frac = (Math.log(1 - 0.5) - Math.log(1 - q)) / (Math.log(1 - 0.5) - Math.log(1 - 0.99));
    var trigger = Math.exp(lo + (hi - lo) * Math.max(0, Math.min(1, frac)));
    var extraLoad = 1 - q;
    var hedgedTail = trigger + a;                       // 触发后再等一个典型响应
    return {value:{
      triggerAtMs:trigger, extraLoadPct:extraLoad * 100,
      tailBefore:b, tailAfter:Math.min(b, hedgedTail),
      improvement:b > 0 ? (1 - Math.min(b, hedgedTail) / b) * 100 : 0,
      safe:extraLoad <= 0.05 + 1e-9,
      note:extraLoad > 0.05 + 1e-9
        ? '触发分位数太低，会带来 ' + (extraLoad * 100).toFixed(0) + '% 的额外流量，通常应在 P95 之后再对冲'
        : '额外流量 ' + (extraLoad * 100).toFixed(1) + '%，属于可接受的尾延迟换吞吐'
    }};
  }

  function analyze(text){
    var pc = parseChain(text);
    if (!pc.ok) return {error:pc.errors[0], errors:pc.errors};
    var rows = pc.value;
    var au = audit(rows);
    var am = amplification(rows);
    var head = rows[0];
    return {value:{
      layers:rows, audit:au, amplification:am,
      endToEndWorst:worstCase(head),
      deepestWorst:worstCase(rows[rows.length - 1]),
      budgetLeft:head.timeout - rows.slice(1).reduce(function(s, r){ return s + worstCase(r); }, 0)
    }, ok:au.ok, grade:au.grade};
  }

  var api = {parseChain:parseChain, worstCase:worstCase, amplification:amplification, audit:audit,
             allocate:allocate, recommend:recommend, retryBudget:retryBudget, hedge:hedge, analyze:analyze};
  if (typeof window !== 'undefined'){ window.__PURE__ = api; }
  if (typeof module !== 'undefined' && module.exports){ module.exports = {TimeoutForgePure:TimeoutForgePure}; }
  return api;
}
